fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();

    if len <= 1 {
        // For empty or single element arrays, put everything in left, right empty
        (a, Vec::new())
    } else {
        // len > 1: split roughly in half
        let mid = len / 2;

        // Since Vec does not have built-in slice partition with ownership,
        // use Vec::split_off method:
        // split_off(mid) leaves the first mid elements in `a` and returns the rest.
        let mut left = a;
        let right = left.split_off(mid);

        (left, right)
    }
}